 object Get(string n)=>typeof(Game1).GetField(n,F)!.GetValue(this)!;void Set(string n,object v)=>typeof(Game1).GetField(n,F)!.SetValue(this,v);object Call(string n,params object[] a)=>typeof(Game1).GetMethod(n,F)!.Invoke(this,a)!; protected override void LoadContent(){Window.Position=new(-3000,-3000);AppContext.SetData("APP_CONTEXT_BASE_DIRECTORY",Environment.GetEnvironmentVariable("GAME_RUNTIME"));w=new(){EquipmentMode=RobotEquipmentMode.Materials};w.SetParticipantCounts(1,1);w.SetWorld(1);w.SetCast(2);w.SetPlacement(3);w.Relations.Reset();w.SelectPlayer(0);w.Relations.Leader=0;w.Robots.Initialize(w.Nodes.All.Length,w.ActiveCount);w.Robots.ConfigureFactories(w);w.Salvage.Reset();w.Salvage.EnableExpeditions(w);foreach(var n in w.Nodes.All)n.Owner=0;int h=w.Nodes.All.First(n=>n.Functional).Id;w.ConquerorLocations[0]=w.Nodes.All[h].Cell;w.ConquerorPoints[0]=w.Nodes.All[h].Center;
 Set("_setup",w);batch=new(GraphicsDevice);var pixel=new Texture2D(GraphicsDevice,1,1);pixel.SetData(new[]{Color.White});Set("_spriteBatch",batch);Set("_pixel",pixel);Content.RootDirectory=Path.Combine(Environment.GetEnvironmentVariable("OLD_RUNTIME")!,"Content");Set("_portraitRenderer",new PortraitRenderer(Content));var fonts=new Microsoft.Xna.Framework.Content.ContentManager(Services,Path.Combine(Environment.GetEnvironmentVariable("PROBE_FONT")!,"Content"));var font=fonts.Load<SpriteFont>("UiFont");Set("_font",font);Set("_ui",Activator.CreateInstance(typeof(Game1).GetField("_ui",F)!.FieldType,batch,pixel,font)!);Set("_conquestAudioUnavailable",true);Set("_screen",Enum.Parse(Get("_screen").GetType(),"WorldStatus"));var cells=w.Cells.GroupBy(c=>c.Face).OrderByDescending(g=>g.Count()).First().Take(3).Select(c=>c.Id).ToHashSet();foreach(var n in w.Nodes.All)n.Owner=cells.Contains(n.Cell)?0:-1;Call("BeginConquestOverview");var presentation=(ConquestPresentation)Get("_conquestPresentation");Set("_conquestCard",Array.FindIndex(presentation.Cards,c=>c.Ruler==0&&!c.Reminder));Call("SetConquestCard");Set("_conquestStage",4);} protected override void Update(GameTime t){}
 protected override void Draw(GameTime t){
 Set("_conquestAge",frame==0?0d:1+frame*.18+.01);Call("UpdateConquestOverview",0d,false);
