 using var image=new RenderTarget2D(GraphicsDevice,1920,1080);GraphicsDevice.SetRenderTarget(image);base.Draw(t);GraphicsDevice.SetRenderTarget(null);using(var file=File.Create(Path.Combine(output,"conquest-flags-"+frame+".png")))image.SaveAsPng(file,1920,1080);
