 if(++frame==4){Set("_conquestAge",Math.Max(tally.FaceStart,tally.CountEnd)+.01);GraphicsDevice.SetRenderTarget(flags);GraphicsDevice.Clear(Color.Transparent);batch.Begin();Call("DrawConquestTerritoryFlags");batch.End();flags.GetData(pixels);GraphicsDevice.SetRenderTarget(null);if(pixels.Any(p=>p.A>0))throw new Exception("Flags must stay inside studio cut");Console.WriteLine("PASS no flags leak into location report");Exit();}
